style.css:
@-moz-document domain("roblox.com") {
#header {
        background-color: #0074bd !important;
        border: none !important;
        box-shadow: none !important;
    }

    .rbx-header .text-header {
        color: #f7f7f8 !important;
    }

    a.text-header[href*="/charts"]::before {
        content: "Games";
        color: #f7f7f8;
    }
    a.text-header[href*="/charts"] {
        color: transparent !important;
    }

    a.text-header[href*="/catalog"]::before {
        content: "Catalog";
        color: #f7f7f8;
    }
    a.text-header[href*="/catalog"] {
        color: transparent !important;
    }

    a.text-header[href*="/create"]::before {
        content: "Develop";
        color: #f7f7f8;
    }
    a.text-header[href*="/create"] {
        color: transparent !important;
    }

    /* Right side icons and text */
    #nav-robux-icon,
    #nav-robux-icon span,
    #nav-robux-amount,
    .rbx-navbar-right .text-header,
    .notification-red,
    .icon-nav-robux,
    .rbx-navbar-right .rbx-menu-icon,
    .rbx-navbar-right span,
    .rbx-navbar-right a {
        color: #f7f7f8 !important;
        fill: #f7f7f8 !important;
    }

    /* Optional: icon hover and active states */
    .rbx-navbar-right .rbx-menu-icon:hover,
    .rbx-navbar-right a:hover {
        color: #ffffff !important;
        fill: #ffffff !important;
    }
}
